<?php
namespace App\Application\Documentos;
use App\Application\Contexto\ContextoOperativo; use App\Models\{Documento,DocumentoVersion,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Database\Eloquent\ModelNotFoundException; use Illuminate\Support\Facades\Storage; use Symfony\Component\HttpFoundation\StreamedResponse;
final class DescargarVersionDocumento { public function __construct(private readonly ConsultaDocumentosContextuales $q){} public function ejecutar(ContextoOperativo $c,User $u,Documento $d,DocumentoVersion $v):StreamedResponse{$d=$this->q->resolver($c,$d->id);$v=$this->q->resolverVersion($c,$d,$v->id);if(!$u->can('view',$d))throw new AuthorizationException();$h=now()->toDateString();if($v->estado->value!=='aprobada'||($v->vigente_desde&&$v->vigente_desde->toDateString()>$h)||($v->vigente_hasta&&$v->vigente_hasta->toDateString()<$h))throw (new ModelNotFoundException())->setModel(DocumentoVersion::class,[$v->id]);$disk=Storage::disk('local');if(!$disk->exists($v->ruta_archivo))throw (new ModelNotFoundException())->setModel(DocumentoVersion::class,[$v->id]);return $disk->download($v->ruta_archivo,$v->nombre_original);}}
